<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();$error='';$u=current_user();$publisher=campus_staff()||$u['role']==='Teacher';
if($_SERVER['REQUEST_METHOD']==='POST')try{publish_announcement($_POST);set_flash('success','Announcement published to the selected audience.');redirect('announcements.php');}catch(InvalidArgumentException $e){$error=$e->getMessage();}
[$where,$params]=announcement_scope();$items=rows('SELECT a.* FROM announcements a WHERE '.$where.' ORDER BY a.id DESC LIMIT 100',$params);$sections=rows('SELECT se.* FROM sections se '.($u['role']==='Teacher'?'WHERE se.id IN(SELECT section_id FROM schedules WHERE teacher_id='.teacher_id().')':'').' ORDER BY name');render_header('Campus announcements'); ?>
<div class="page-title"><div><h1>Campus announcements</h1><p>Updates for your role, course, and section.</p></div></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><?php if($publisher): ?><div class="col-lg-5"><section class="panel"><h2>Publish an update</h2><form method="post" class="campus-form"><?= csrf_field() ?><label>Title<input name="title" class="form-control" minlength="3" maxlength="160" required></label><label>Message<textarea name="body" class="form-control" rows="5" minlength="3" maxlength="5000" required></textarea></label><label>Audience<select name="target_role" class="form-select"><?php foreach($u['role']==='Teacher'?['Student','Parent']:['All','Student','Parent','Teacher','Admin'] as $role): ?><option><?= e($role) ?></option><?php endforeach; ?></select></label><label>Course<select name="target_course_id" class="form-select"><option value="">All matching courses</option><?php foreach(option_list('courses','code') as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['label']) ?></option><?php endforeach; ?></select></label><label>Section<select name="target_section_id" class="form-select" <?= $u['role']==='Teacher'?'required':'' ?>><option value="">All matching sections</option><?php foreach($sections as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary">Publish announcement</button></form></section></div><?php endif; ?><div class="<?= $publisher?'col-lg-7':'col-12' ?>"><section class="panel"><h2>Latest updates</h2><?php if(!$items)empty_state('No announcements for your audience');foreach($items as $a): ?><article class="campus-event"><h3><?= e($a['title']) ?></h3><p class="campus-preserve"><?= e($a['body']) ?></p><small><?= e($a['target_role'].' · '.campus_time($a['created_at'])) ?></small></article><?php endforeach; ?></section></div></div><?php render_footer(); ?>
